{
  "formular": "Austrittsmeldung",
  "felder": [
    {
      "feld": "Nachname",
      "vorgabe": "Der Nachname der versicherten Person muss vollständig und korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Vorname",
      "vorgabe": "Der Vorname der versicherten Person muss vollständig und korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Geburtsdatum",
      "vorgabe": "Das exakte Geburtsdatum (TT.MM.JJJJ) muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Nationalität",
      "vorgabe": "Die Nationalität der versicherten Person muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Versichert-en-Nr.",
      "vorgabe": "Die eindeutige Versichertennummer muss korrekt eingetragen werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Aufenthaltsbewilligung",
      "vorgabe": "Falls vorhanden, muss die Nummer oder Art der Aufenthaltsbewilligung angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Beruf",
      "vorgabe": "Der ausgeübte Beruf muss korrekt und vollständig angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Strasse/Nr.",
      "vorgabe": "Die vollständige Strassenadresse inklusive Hausnummer muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Ort",
      "vorgabe": "Der Wohnort (Gemeinde) muss korrekt angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "PLZ",
      "vorgabe": "Die korrekte Postleitzahl des Wohnortes muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Telefon",
      "vorgabe": "Eine gültige Telefonnummer für Rückfragen muss angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "E-Mail",
      "vorgabe": "Eine gültige E-Mail-Adresse muss angegeben werden, falls gewünscht.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Geschichte (männlich/weiblich)",
      "vorgabe": "Das Geschlecht muss durch Ankreuzen der zutreffenden Option angegeben werden.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Erklärung der versicherten Person (Austrittsstatus)",
      "vorgabe": "Es muss angegeben werden, ob die Person bereits ausgetreten ist oder den Austritt plant.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Austrittsdatum",
      "vorgabe": "Das genaue Datum des Austritts aus der Firma muss angegeben werden (TT.MM.JJJJ).",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Interesse an Weiterführung",
      "vorgabe": "Es muss angekreuzt werden, ob eine unverbindliche Offerte für die Weiterführung der Versicherung gewünscht wird oder ob auf das Recht zur Weiterführung verzichtet wird.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Unterschrift",
      "vorgabe": "Die Unterschrift der versicherten Person muss vorhanden sein.",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    },
    {
      "feld": "Datum",
      "vorgabe": "Das Datum der Unterzeichnung muss angegeben werden (TT.MM.JJJJ).",
      "quelle": "keine sichere Quelle",
      "sicherheit": "niedrig"
    }
  ]
}
